import { ScrollView, View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

const ANGILAL = ["Гар утас", "Компьютер", "Гэр ахуй", "Хувцас", "Гоо сайхан", "Спорт", "Ном", "Тоглоом"];

function App() {
  return (
    <ScrollView style={styles.screen} contentContainerStyle={styles.content}>
      <Text style={styles.h}>Ангилал</Text>
      {ANGILAL.map((name, i) => (
        <Text key={i} testID="cat" style={styles.row}>{name}</Text>
      ))}
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#f5f6f8" },
  content: { padding: 16, gap: 10 },
  h: { fontSize: 22, fontWeight: "bold", marginBottom: 8 },
  row: { padding: 16, backgroundColor: "#ffffff", borderRadius: 12, fontSize: 16 },
});

registerRootComponent(App);
